#!/usr/bin/env python3
from pathlib import Path
import argparse,json,hashlib
ap=argparse.ArgumentParser();ap.add_argument('--candidate-root',required=True);ap.add_argument('--handoff-zip',required=True);ap.add_argument('--handoff-identity',required=True);ap.add_argument('--source-candidate-sha256',default='');ap.add_argument('--repair-contract-sha256',default='');a=ap.parse_args();root=Path(a.candidate_root).resolve();identity=json.loads(Path(a.handoff_identity).read_text(encoding='utf-8'));z=Path(a.handoff_zip).resolve();h=hashlib.sha256(z.read_bytes()).hexdigest();obj={'status':'BOUND','originating_handoff_id':identity['handoff_id'],'originating_handoff_sha256':h,'orchestration_os_version':identity['orchestration_os_version'],'audit_os_version':identity['audit_os_version'],'contract_generation':identity['contract_generation'],'expected_output_name':identity['expected_output_name'],'source_candidate_sha256':a.source_candidate_sha256,'repair_contract_sha256':a.repair_contract_sha256};p=root/'handoff/contract_lineage.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps(obj,indent=2))
